import { OnDestroy } from '@angular/core';
import { Subject } from 'rxjs/Subject';
import { takeUntil } from 'rxjs/operators';
// --------------------------------------
private _destroyedSubscribe$: Subject<void> = new Subject<void>();
// --------------------------------------
    $TEXT$
    .pipe(takeUntil(this._destroyedSubscribe$))
    .subscribe({
        next: (result) => { console.log('result', result); },
        error: (err) => { console.error('Ошибка:', err); // здесь можно показать уведомление или выполнить fallback-логику },
        complete: () => { console.log('Поток завершён'); }
    });
// --------------------------------------
public ngOnDestroy(): void {
    this._destroyedSubscribe$.next();
    this._destroyedSubscribe$.complete();
}
