// Если union‑тип (Direction) изменится, TypeScript выдаст ошибку компиляции, если switch не обновлён.
type Direction = 'up' | 'down';

public move(direction: Direction): number {
    switch (direction) {
        case 'up': return 1;
        case 'down': return -1;
        default:
          //!!! Если добавлен новый вариант в `Direction` и не обработан — ошибка компиляции
          const _: never = direction;
          throw new Error(`Неизвестный ключ: ${_}`);
    }
}

